void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Target graph and result map must not be null or empty");
    }

    Set<V> leftPartition = new HashSet<>();
    Set<V> rightPartition = new HashSet<>(resultMap.values());

    // Assuming we need to split the vertices into two partitions
    // For simplicity, we'll put half of the vertices in the left partition and the other half in the right partition
    int size = rightPartition.size();
    int midpoint = size / 2;
    Iterator<V> iterator = rightPartition.iterator();
    for (int i = 0; i < midpoint && iterator.hasNext(); i++) {
        leftPartition.add(iterator.next());
        iterator.remove();
    }

    // Add all vertices to the graph
    target.addAllVertices(leftPartition);
    target.addAllVertices(rightPartition);

    // Create edges between every vertex in the left partition and every vertex in the right partition
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

