static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Create a calendar instance to manipulate the date
    java.util.Calendar calendar = java.util.Calendar.getInstance();
    calendar.set(year, month - 1, day); // Month is 0-based in Calendar

    // Calculate the difference in days from the start of the month
    int dayOfMonth = calendar.get(java.util.Calendar.DAY_OF_MONTH);
    int remainder = (dayOfMonth - 1) % dayStep;

    // Adjust the day to align with the dayStep
    calendar.add(java.util.Calendar.DAY_OF_MONTH, -remainder);

    // Get the new year, month, and day
    int newYear = calendar.get(java.util.Calendar.YEAR);
    int newMonth = calendar.get(java.util.Calendar.MONTH) + 1; // Convert back to 1-based month
    int newDay = calendar.get(java.util.Calendar.DAY_OF_MONTH);

    // Return the new time bucket
    return newYear * 10000L + newMonth * 100L + newDay;
}

