LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("Write session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int length = str.length();
    int offset = 0;
    int remaining = lb.remaining();
    byte[] buffer = lb.buffer();

    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);

        if (c < 0x80) {
            if (remaining < 1) {
                lb = lb.next = session.next(lb, 1);
                buffer = lb.buffer();
                remaining = lb.remaining();
                offset = 0;
            }
            buffer[offset++] = (byte) c;
            remaining--;
        } else if (c < 0x800) {
            if (remaining < 2) {
                lb = lb.next = session.next(lb, 2);
                buffer = lb.buffer();
                remaining = lb.remaining();
                offset = 0;
            }
            buffer[offset++] = (byte) (0xc0 | (c >> 6));
            buffer[offset++] = (byte) (0x80 | (c & 0x3f));
            remaining -= 2;
        } else if (c < 0x10000) {
            if (remaining < 3) {
                lb = lb.next = session.next(lb, 3);
                buffer = lb.buffer();
                remaining = lb.remaining();
                offset = 0;
            }
            buffer[offset++] = (byte) (0xe0 | (c >> 12));
            buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            buffer[offset++] = (byte) (0x80 | (c & 0x3f));
            remaining -= 3;
        } else {
            i--; // Surrogate pair is two chars, but we'll handle one in this iteration
            char low;
            if ((i + 1) < length) {
                low = str.charAt(i + 1);
            } else {
                throw new IllegalArgumentException("Unmatched high surrogate at end of string");
            }
            if (!Character.isLowSurrogate(low)) {
                throw new IllegalArgumentException("Expected low surrogate character");
            }
            int codePoint = Character.toCodePoint(c, low);
            i++;

            if (remaining < 4) {
                lb = lb.next = session.next(lb, 4);
                buffer = lb.buffer();
                remaining = lb.remaining();
                offset = 0;
            }
            buffer[offset++] = (byte) (0xf0 | (codePoint >> 18));
            buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
            buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
            buffer[offset++] = (byte) (0x80 | (codePoint & 0x3f));
            remaining -= 4;
        }
    }

    lb.offset = offset;
    return lb;
}

