List<PathSegmentImpl> function ( URI u , boolean decode ) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u == null || u.getPath() == null || u.getPath().isEmpty()) {
        return pathSegments;
    }

    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    String[] segments = path.split("/");
    for (String segment : segments) {
        if (!segment.isEmpty()) {
            if (decode) {
                try {
                    segment = URLDecoder.decode(segment, "UTF-8");
                } catch (UnsupportedEncodingException e) {
                    throw new RuntimeException("UTF-8 encoding not supported", e);
                }
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }

    return pathSegments;
}

