void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }
    try {
        byte[] buffer = new byte[in.available()];
        int bytesRead = in.read(buffer);
        if (bytesRead == -1) {
            buffer = new byte[0]; // Stream was empty
        } else if (bytesRead < buffer.length) {
            // If not all bytes were read in one go, read the rest
            ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
            byteStream.write(buffer, 0, bytesRead);
            byte[] tempBuffer = new byte[1024];
            int read;
            while ((read = in.read(tempBuffer)) != -1) {
                byteStream.write(tempBuffer, 0, read);
            }
            buffer = byteStream.toByteArray();
        }
        this.buffer = buffer;
        this.position = 0; // Reset the read pointer
    } finally {
        in.close();
    }
}

