@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() == 1) {
                return strValue.charAt(0);
            } else {
                throw new IllegalArgumentException("String length must be exactly 1 to convert to Character.");
            }
        } else if (value instanceof Number) {
            int intValue = ((Number) value).intValue();
            if (intValue >= Character.MIN_VALUE && intValue <= Character.MAX_VALUE) {
                return (char) intValue;
            } else {
                throw new IllegalArgumentException("Number out of range for Character conversion.");
            }
        } else {
            throw new IllegalArgumentException("Cannot convert " + value.getClass().getName() + " to Character.");
        }
    } else {
        throw new IllegalArgumentException("Type " + type.getName() + " is not supported for conversion to Character.");
    }
}

