GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0.0, new LinkedList<>());
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    for (E edge : edgeList) {
        V targetVertex = graph.getEdgeTarget(edge);
        vertexList.add(targetVertex);
        startVertex = targetVertex; // Move to the next vertex
    }

    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), graphTypeDependantEdgeWeightSum(graph, edgeList), vertexList);
}

private double graphTypeDependantEdgeWeightSum(Graph<V, E> graph, List<E> edgeList) {
    double weightSum = 0.0;
    if (graph instanceof WeightedGraph) {
        for (E edge : edgeList) {
            weightSum += ((WeightedGraph<V, E>) graph).getEdgeWeight(edge);
        }
    }
    return weightSum;
}

