private Integer findMaxLowerBound(List<K> keys, int currentIndex) {
    K currentKey = keys.get(currentIndex);
    Integer maxLowerBound = null;
    for (int i = 0; i < currentIndex; i++) {
        K key = keys.get(i);
        if (isLessThan(key, currentKey)) {
            if (maxLowerBound == null || isGreaterThan(key, keys.get(maxLowerBound))) {
                maxLowerBound = i;
            }
        }
    }
    return maxLowerBound;
}

private boolean isLessThan(K a, K b) {
    if (a instanceof Comparable && b instanceof Comparable) {
        return ((Comparable<K>) a).compareTo(b) < 0;
    }
    throw new IllegalArgumentException("Keys must be comparable");
}

private boolean isGreaterThan(K a, K b) {
