    throw new IllegalArgumentException("Keys must be comparable");
}

void pop(final String descriptor) {
    int descriptorIndex = 0;
    if (descriptor.charAt(0) == '(') { // Method descriptor
        descriptorIndex = 1;
        while (descriptor.charAt(descriptorIndex) != ')') {
            descriptorIndex = popType(descriptor, descriptorIndex);
        }
        descriptorIndex++; // Skip ')'
    }
    // Now pop the return type if it's not void
    if (descriptorIndex < descriptor.length() && descriptor.charAt(descriptorIndex) != 'V') {
        popType(descriptor, descriptorIndex);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': // byte
        case 'C': // char
        case 'D': // double
        case 'F': // float
        case 'I': // int
        case 'S': // short
        case 'Z': // boolean
            // These are all single-slot types, do nothing
            break;
        case 'J': // long
            // Long is a double-slot type, do nothing
            break;
        case 'L': // Object
        case '[': // Array
            // Both are reference types, do nothing
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            if (descriptor.charAt(index) == 'L') {
                index = descriptor.indexOf(';', index) + 1;
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor at index " + index + ": " + descriptor);
    }
    return index;
}

