List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        if (key instanceof Comparable) {
            try {
                Comparable<K> comparableKey = (Comparable<K>) key;
                upperBounds.add(comparableKey.compareTo(key) + 1);
            } catch (ClassCastException e) {
                // Handle the case where key is not comparable to itself
                upperBounds.add(Integer.MAX_VALUE);
            }
        } else {
            // Handle the case where key is not comparable
            upperBounds.add(Integer.MAX_VALUE);
        }
    }
    return upperBounds;
}

