String function ( String path , String relativePath ) { 
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }
    if (relativePath.isEmpty()) {
        return path;
    }
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");
    int position = pathParts.length - 1;

    for (String part : relativePathParts) {
        if (part.equals("..")) {
            if (position > 0) {
                position--;
            }
        } else if (part.equals(".")) {
            // Stay in the same place
        } else {
            pathParts[position] = part;
            position++;
        }
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= position; i++) {
        if (i != 0) {
            result.append("/");
        }
        result.append(pathParts[i]);
    }

    return result.toString();
}

