    if (str == null || substring == null || index < 0) {
        return false;
    }
    int subLen = substring.length();
    if (subLen == 0) {
        return true;
    }
    if (index + subLen > str.length()) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

