List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        return snapshots;
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            if (snapshot != null) {
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range.isWithinRange(snapshot.getTimestamp())) {
                        snapshots.add(snapshot);
                        break;
                    }
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading from file: " + file.getAbsolutePath(), e);
    }

    return snapshots;
}

private static ThreadSnapshot parseThreadSnapshot(String line) {
    // This method should be implemented to parse a line from the file into a ThreadSnapshot object.
    // Placeholder implementation assumes line format: "timestamp,threadId,threadName,state".
    String[] parts = line.split(",");
